# application.yml  (antes WKS-ARCH-INTELAR y el FD REPORTE)
p671:
  directorio: "S151/FILE/INTS/15110S01"        # usuario (S151) y familia CMEMP por ambiente
  familia: CMEMP
  titulo: "{dir}/{csi}/{interfaz}/{fecha}/{hhmmss}/CSV"
  permisos-archivo: "rw-r-----"                # el fuente declara SECURITYTYPE PUBLIC
  max-registro: 400                            # MAXRECSIZE IS 400

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class IntelarArchivo {

    private final P671Properties props;
    private final Clock reloj;

    /** WKS-ARCH-INTELAR: fecha del parámetro (8 dígitos) y hora de la máquina en el nombre. */
    public Path ruta(int csi, Interfaz interfaz, LocalDate fechaParametro) {
        String hhmmss = LocalTime.now(reloj).format(DateTimeFormatter.ofPattern("HHmmss"));
        return Path.of(props.titulo()
                .replace("{dir}", props.directorio())
                .replace("{csi}", "%02d".formatted(csi))
                .replace("{interfaz}", interfaz.nombreArchivo())     // PROTECCOB, ALERTANOT, DOMICILIA
                .replace("{fecha}", fechaParametro.format(DateTimeFormatter.BASIC_ISO_DATE))
                .replace("{hhmmss}", hhmmss));
    }

    /** Se crea con permisos restringidos: el CSV lleva cliente, contrato, cuenta y CLABE. */
    public BufferedWriter abre(Path p) throws IOException {
        Files.createDirectories(p.getParent());
        Files.createFile(p, PosixFilePermissions.asFileAttribute(
                PosixFilePermissions.fromString(props.permisosArchivo())));
        return Files.newBufferedWriter(p, StandardCharsets.UTF_8);
    }
}

/** WKS-DET-B07: los campos se separan con FILLER VALUE ","; el ancho de cada PIC se conserva. */
public record ProteccionCobroCsv(int numId, String numCte, String contrato, int medAcceso,
                                 int mdaPref, String mdaCuenta, long autAplic,
                                 int fecCargo, int hrCargo, long autPc,
                                 BigDecimal importe,          // PIC 9(014).9(02): sin signo
                                 long autS151, long autAntS151, int cveTrans,
                                 int numOcurr, int numProc, int status, int numEnv,
                                 int tipoMov, int numError, String datGen, int hrEnvio) {

    static final String ENCABEZADO = "Id,Cte,Contrato,Cve Acceso,Suc mda,Cuenta,Aut Apli,Fec Carg,"
            + "Hr Carg,Aut pc,importe,Aut S151,Aut Ant S151,Cve,Ocurr,Num "
            + "Pro,Estatus,Num Env,Tipo Mov,Num Error,Dat Gen,Hr Envio";

    String linea() {
        return String.join(",",
                "%02d".formatted(numId), ceros(numCte, 12), ceros(contrato, 16),
                "%04d".formatted(medAcceso), "%04d".formatted(mdaPref), ceros(mdaCuenta, 16),
                "%08d".formatted(autAplic), "%06d".formatted(fecCargo), "%06d".formatted(hrCargo),
                "%012d".formatted(autPc), Importe.editado(importe, 14, 2),   // trunca el signo, como el PIC
                "%08d".formatted(autS151), "%08d".formatted(autAntS151), "%04d".formatted(cveTrans),
                "%02d".formatted(numOcurr), "%02d".formatted(numProc), "%02d".formatted(status),
                "%04d".formatted(numEnv), "%04d".formatted(tipoMov), "%04d".formatted(numError),
                Csv.texto(datGen, 147),                                        // ver riesgo
                "%06d".formatted(hrEnvio));
    }
}

@Service
@RequiredArgsConstructor
public class ExtractorIntelarService {

    private final IntelarArchivo archivo;
    private final ProteccionCobroRepository b07;   // S151B07PROTCOB
    private final DomiciliacionRepository b10;     // S151B10DOMI
    private final HostInfo host;                   // CSIID IN SOPORTECOMS

    /** 000000-INIC-PROGRAMA + 00100-PROCESO. Una sola transacción de lectura (OPEN INQUIRY). */
    @Retryable(retryFor = CannotGetJdbcConnectionException.class,
               maxAttempts = 7, backoff = @Backoff(delay = 10_000))      // W77-INTENTO > 6, WAIT(10)
    @Transactional(readOnly = true)
    public Path genera(ParametroIntelar p) throws IOException {
        var caso = p.caso().orElseThrow(() -> new ParametroInvalidoException("PARAMETRO INVALIDO"));
        Path ruta = archivo.ruta(host.csi(), p.interfaz(), p.fecha());
        try (var w = archivo.abre(ruta)) {                                // OPEN OUTPUT REPORTE
            switch (p.interfaz()) {
                case PROTECCION_COBRO, ALERTAS -> exportaB07(w, p, caso);    // 00121-BUSCAB07
                case DOMICILIACION             -> exportaB10(w, p, caso);    // 00130-BUSCAB10
            }
        }                                                                  // CLOSE REPORTE WITH SAVE
        return ruta;
    }

    @Recover
    Path sinBase(CannotGetJdbcConnectionException e, ParametroIntelar p) {
        throw new ProcesoAbortadoException("ERROR AL ABRIR LA S151BD13BIFIN", e);   // STATUS -1
    }
}

public enum Interfaz {
    PROTECCION_COBRO(1, "PROTECCOB"), ALERTAS(2, "ALERTANOT"), DOMICILIACION(3, "DOMICILIA");

    private final int id; private final String nombreArchivo;
    Interfaz(int id, String nombre) { this.id = id; this.nombreArchivo = nombre; }
    public String nombreArchivo() { return nombreArchivo; }

    static Optional<Interfaz> de(int id) {
        return Arrays.stream(values()).filter(i -> i.id == id).findFirst();
    }
}

/** WKSPARAMETRO: id 9(02), fecha 9(08) (solo se usa AAMMDD), contrato 9(16). */
public record ParametroIntelar(int id, int fecha8, String contrato) {

    public enum Caso { POR_FECHA, POR_FECHA_Y_CONTRATO }

    /** 00110-VAL-PARAM: la fecha se valida y se busca con sus 6 dígitos bajos (AAMMDD). */
    public Optional<Caso> caso() {
        int aammdd = fecha8 % 1_000_000;
        if (aammdd <= 0 || Interfaz.de(id).isEmpty()) return Optional.empty();
        return Optional.of(new BigInteger(contrato).signum() == 0 ? Caso.POR_FECHA : Caso.POR_FECHA_Y_CONTRATO);
    }

    public int fechaBusqueda() { return fecha8 % 1_000_000; }        // B07-FEC-CARGO es AAMMDD
    public Interfaz interfaz()  { return Interfaz.de(id).orElseThrow(); }
    public LocalDate fecha()    { return LocalDate.parse("%08d".formatted(fecha8), DateTimeFormatter.BASIC_ISO_DATE); }
}

public interface ProteccionCobroRepository extends JpaRepository<ProteccionCobro, Long> {

    /** B07SXFECHA: FIND FIRST / FIND NEXT AT B07-NUM-ID y B07-FEC-CARGO. */
    @QueryHints(@QueryHint(name = HINT_FETCH_SIZE, value = "500"))
    Stream<ProteccionCobro> findByNumIdAndFecCargoOrderByIndiceB07(int numId, int fecCargo);

    /** Caso 2: la llave del índice incluye el contrato, así que el filtro es exacto. */
    Stream<ProteccionCobro> findByNumIdAndFecCargoAndContratoOrderByIndiceB07(int numId, int fecCargo, String contrato);
}

/** 00121-BUSCAB07: encabezado y una línea por registro. */
void exportaB07(BufferedWriter w, ParametroIntelar p, ParametroIntelar.Caso caso) throws IOException {
    w.write(ProteccionCobroCsv.ENCABEZADO); w.newLine();
    try (Stream<ProteccionCobro> s = (caso == ParametroIntelar.Caso.POR_FECHA)
            ? b07.findByNumIdAndFecCargoOrderByIndiceB07(p.id(), p.fechaBusqueda())
            : b07.findByNumIdAndFecCargoAndContratoOrderByIndiceB07(p.id(), p.fechaBusqueda(), p.contrato())) {
        for (var r : (Iterable<ProteccionCobro>) s::iterator) {
            w.write(ProteccionCobroCsv.de(r).linea()); w.newLine();   // 00122-GRABA-REGISTRO
        }
    }
}

public interface DomiciliacionRepository extends JpaRepository<Domiciliacion, Long> {

    /** B10SXFECAUT151: el índice es por interfaz y fecha; el contrato NO forma parte de la llave. */
    Stream<Domiciliacion> findByNumIdAndFecCargoOrderByIndiceB10(int numId, int fecCargo);
}

/** 00130-BUSCAB10. */
void exportaB10(BufferedWriter w, ParametroIntelar p, ParametroIntelar.Caso caso) throws IOException {
    w.write(DomiciliacionCsv.ENCABEZADO); w.newLine();
    try (Stream<Domiciliacion> s = b10.findByNumIdAndFecCargoOrderByIndiceB10(p.id(), p.fechaBusqueda())) {
        Stream<Domiciliacion> filas = (caso == ParametroIntelar.Caso.POR_FECHA)
                ? s
                // Comportamiento del COBOL: se detiene en el primer registro de otro contrato.
                // Con p671.domiciliacion.filtro-completo = true se usaría s.filter(...) en su lugar.
                : (props.domiciliacion().filtroCompleto()
                        ? s.filter(r -> r.contrato().equals(p.contrato()))
                        : s.takeWhile(r -> r.contrato().equals(p.contrato())));
        for (var r : (Iterable<Domiciliacion>) filas::iterator) {
            w.write(DomiciliacionCsv.de(r).linea()); w.newLine();     // 00122-GRABA-REGISTRO2
        }
    }
}

/** 00122-GRABA-REGISTRO: un MOVE por campo de B07 al layout CSV y WRITE ... FROM. */
static ProteccionCobroCsv de(ProteccionCobro r) {
    return new ProteccionCobroCsv(
            r.numId(), r.numCte(), r.contrato(), r.medAcceso(), r.mdaPref(), r.mdaCuenta(),
            r.autAplic(), r.fecCargo(), r.hrCargo(), r.autPc(), r.importe(),
            r.autS151(), r.autAntS151(), r.cveTrans(), r.numOcurr(), r.numProc(),
            r.status(), r.numEnv(), r.tipoMov(), r.numError(), r.datGen(), r.hrEnvio());
}

/** 00122-GRABA-REGISTRO2: igual para B10, con CLABE como String de 18 posiciones. */
static DomiciliacionCsv de(Domiciliacion r) {
    return new DomiciliacionCsv(r.numId(), r.cuentaClabe(), r.numCte(), r.contrato(), /* ... */
                                r.sucProm());
}
